const body = $input.first().json.body || $input.first().json;
const msg = body.message || body;

// Tool call data
const toolCallList = msg.toolCallList || msg.toolCalls || [];
const toolCall = toolCallList[0] || {};
const toolCallId = toolCall.id || 'unknown';
let args = {};
try { args = JSON.parse(toolCall.function?.arguments || '{}'); } catch(e) {}

// Call data
const call = msg.call || {};
const telefono = (call.customer?.number || '').replace(/^\+/, '');
const callId = call.id || '';

// Transcript
const transcript = msg.artifact?.transcript || msg.transcript || '';
const messages = msg.artifact?.messages || [];

// Build historial from messages
const historial = messages
  .filter(m => m.role === 'user' || m.role === 'assistant')
  .map(m => {
    const rol = m.role === 'user' ? 'Cliente' : 'Alex';
    return `[Llamada] ${rol}: ${m.message || m.content || ''}`;
  })
  .join('\n');

return [{ json: {
  toolCallId,
  autorizado: args.autorizado !== false,
  telefono,
  callId,
  transcript,
  historial: historial || `[Llamada] Transcript: ${transcript.slice(0, 1000)}`
}}];

