const extractData = $('🔧 Extraer Datos Llamada').item.json;
const groqRaw = $input.first().json;

let leadData = { producto: '', medidas: '', fecha: '', nombre_cliente: '', idioma: 'es', resumen: 'Llamada recibida' };
try {
  const content = groqRaw.choices?.[0]?.message?.content || '{}';
  leadData = { ...leadData, ...JSON.parse(content) };
} catch(e) {}

const esEspanol = leadData.idioma !== 'en';
const producto = leadData.producto || 'tu artículo';
const resumen = leadData.resumen || '';

let mensajeWA;
if (esEspanol) {
  mensajeWA = `Hola 👋 soy Alex de Crating Express. Gracias por tu llamada.\n\n`;
  if (resumen) mensajeWA += `${resumen}\n\n`;
  mensajeWA += `Puedes continuar tu cotización aquí respondiendo este mensaje, o ver precios en: https://cratingcotiza.mdarthurdigital.com/cotizar-caja\n\n¿Tienes alguna pregunta?`;
} else {
  mensajeWA = `Hi 👋 this is Alex from Crating Express. Thanks for your call.\n\n`;
  if (resumen) mensajeWA += `${resumen}\n\n`;
  mensajeWA += `You can continue your quote here by replying to this message, or check prices at: https://cratingcotiza.mdarthurdigital.com/cotizar-caja\n\nAny questions?`;
}

// Historial para Airtable
const historialConResumen = extractData.historial + 
  (resumen ? `\n[Resumen] ${resumen}` : '');

return [{ json: {
  ...extractData,
  mensajeWA,
  producto: leadData.producto || null,
  medidas: leadData.medidas || null,
  fecha: leadData.fecha || null,
  historialCompleto: historialConResumen
}}];

